// Send a Gmail message through the unified Google connection (Nango OAuth).
// callProvider('google', ...) routes by tool NAME to the nango://google
// connection; the 5th arg baseUrlOverride points THIS call at gmail.googleapis.com
// (Calendar/Drive use the provider default www.googleapis.com — no override).
const GMAIL_HOST = 'https://gmail.googleapis.com';
const to = String(args?.to ?? '').trim();
const subject = String(args?.subject ?? '').trim();
const bodyText = String(args?.body ?? '');
if (!to) throw new Error('gmail_send: to is required');
if (!subject) throw new Error('gmail_send: subject is required');

const mime = [
  'To: ' + to,
  'Subject: ' + subject,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  '',
  bodyText
].join('\r\n');

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const utf8Bytes = (str) => {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let c = str.charCodeAt(i);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) { out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f)); }
    else if (c >= 0xd800 && c <= 0xdbff) {
      const c2 = str.charCodeAt(++i);
      c = 0x10000 + ((c & 0x3ff) << 10) + (c2 & 0x3ff);
      out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else { out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f)); }
  }
  return out;
};
const base64 = (bytes) => {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i + 1], b2 = bytes[i + 2];
    s += B64[b0 >> 2];
    s += B64[((b0 & 3) << 4) | ((b1 ?? 0) >> 4)];
    s += b1 === undefined ? '=' : B64[((b1 & 15) << 2) | ((b2 ?? 0) >> 6)];
    s += b2 === undefined ? '=' : B64[b2 & 63];
  }
  return s;
};
const raw = base64(utf8Bytes(mime)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const res = await callProvider('google', 'POST', '/gmail/v1/users/me/messages/send', { raw }, { baseUrlOverride: GMAIL_HOST });
const ok = res?.status ? res.status >= 200 && res.status < 300 : true;
const messageId = res?.body?.id ?? null;

await propose.entity({
  profileSlug: 'note',
  title: 'Email ' + (ok ? 'sent' : 'attempted') + ' -> ' + to + ': ' + subject,
  properties: { action: 'gmail_send', to, subject, gmailMessageId: messageId, status: res?.status ?? null, success: ok, source: 'nango-google' },
  reasoning: 'Recorded the outbound email for the activity timeline.'
});
return { success: ok, to, subject, gmailMessageId: messageId, status: res?.status ?? null };

// Search Gmail and return enriched headers (Subject/From/Date) for each hit.
// Read-only: lists message ids, then fetches metadata per id (bounded).
const GMAIL_HOST = 'https://gmail.googleapis.com';
const q = String(args?.query ?? '').trim();
const maxResults = Math.min(Number(args?.maxResults ?? 10) || 10, 25);
const listPath = '/gmail/v1/users/me/messages?maxResults=' + maxResults + (q ? '&q=' + encodeURIComponent(q) : '');
const listRes = await callProvider('google', 'GET', listPath, undefined, { baseUrlOverride: GMAIL_HOST });
const ids = (listRes?.body?.messages ?? []).map((m) => m.id);
const results = [];
for (const id of ids) {
  try {
    const mPath = '/gmail/v1/users/me/messages/' + id + '?format=metadata&metadataHeaders=Subject&metadataHeaders=From&metadataHeaders=Date';
    const mRes = await callProvider('google', 'GET', mPath, undefined, { baseUrlOverride: GMAIL_HOST });
    const headers = mRes?.body?.payload?.headers ?? [];
    const h = (name) => { const f = headers.find((x) => (x.name || '').toLowerCase() === name); return f ? f.value : null; };
    results.push({ id, subject: h('subject'), from: h('from'), date: h('date'), snippet: mRes?.body?.snippet ?? null });
  } catch (e) { results.push({ id, error: String(e) }); }
}
return { query: q, count: results.length, results };

// List upcoming Google Calendar events (read-only). Uses the provider-default
// host www.googleapis.com (no baseUrlOverride needed for Calendar).
const maxResults = Math.min(Number(args?.maxResults ?? 10) || 10, 50);
const timeMin = String(args?.timeMin ?? '').trim() || new Date().toISOString();
const calendarId = String(args?.calendarId ?? 'primary').trim() || 'primary';
const path = '/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events?singleEvents=true&orderBy=startTime&maxResults=' + maxResults + '&timeMin=' + encodeURIComponent(timeMin);
const res = await callProvider('google', 'GET', path);
const events = (res?.body?.items ?? []).map((e) => ({ id: e.id, summary: e.summary ?? null, start: e.start ?? null, end: e.end ?? null, location: e.location ?? null, htmlLink: e.htmlLink ?? null }));
return { calendarId, count: events.length, events };

// Create a Google Calendar event (proposal-gated write). RFC3339 start/end.
const summary = String(args?.summary ?? '').trim();
if (!summary) throw new Error('calendar_create: summary is required');
const start = String(args?.start ?? '').trim();
const end = String(args?.end ?? '').trim();
if (!start) throw new Error('calendar_create: start is required (RFC3339, e.g. 2026-07-01T15:00:00Z)');
if (!end) throw new Error('calendar_create: end is required (RFC3339)');
const calendarId = String(args?.calendarId ?? 'primary').trim() || 'primary';
const event = { summary, start: { dateTime: start }, end: { dateTime: end } };
if (args?.description) event.description = String(args.description);
if (args?.location) event.location = String(args.location);
const res = await callProvider('google', 'POST', '/calendar/v3/calendars/' + encodeURIComponent(calendarId) + '/events', event);
const ok = res?.status ? res.status >= 200 && res.status < 300 : true;
const eventId = res?.body?.id ?? null;
const htmlLink = res?.body?.htmlLink ?? null;
await propose.entity({
  profileSlug: 'note',
  title: 'Calendar event ' + (ok ? 'created' : 'attempted') + ': ' + summary,
  properties: { action: 'calendar_create', summary, start, end, eventId, htmlLink, status: res?.status ?? null, success: ok, source: 'nango-google' },
  reasoning: 'Recorded the created calendar event for the activity timeline.'
});
return { success: ok, summary, eventId, htmlLink, status: res?.status ?? null };

// Search Google Drive files by name (read-only). Provider-default host.
const q = String(args?.query ?? '').trim();
const pageSize = Math.min(Number(args?.maxResults ?? 10) || 10, 50);
const params = ['pageSize=' + pageSize, 'fields=' + encodeURIComponent('files(id,name,mimeType,webViewLink,modifiedTime)')];
if (q) { const safe = q.replace(/'/g, ''); params.push('q=' + encodeURIComponent("name contains '" + safe + "'")); }
const path = '/drive/v3/files?' + params.join('&');
const res = await callProvider('google', 'GET', path);
const files = (res?.body?.files ?? []).map((f) => ({ id: f.id, name: f.name, mimeType: f.mimeType, webViewLink: f.webViewLink ?? null, modifiedTime: f.modifiedTime ?? null }));
return { query: q, count: files.length, files };
